/* One navigation and contact experience for the homepage and every policy page. */
(()=>{
 const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),menu=$('.topbar-mobileMenuButton'),shell=$('.topbar-mobileShell'),panel=$('#mobile-primary-panel');
 let lockedScroll=0,pageLocked=false,currentNav='',navFrame=0;
 function syncPageLock(){const lock=menu?.getAttribute('aria-expanded')==='true'||Boolean($('dialog[open]'));if(lock===pageLocked)return;pageLocked=lock;if(lock){lockedScroll=scrollY;document.body.style.setProperty('--locked-scroll',-lockedScroll+'px');document.body.classList.add('page-locked')}else{document.body.classList.remove('page-locked');document.body.style.removeProperty('--locked-scroll');const behavior=document.documentElement.style.scrollBehavior;document.documentElement.style.scrollBehavior='auto';scrollTo(0,lockedScroll);document.documentElement.style.scrollBehavior=behavior}}
 function toggleMenu(open){if(!menu)return;shell.dataset.open=String(open);shell.classList.toggle('topbar-mobileShellOpen',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');panel.classList.toggle('topbar-mobilePanelOpen',open);panel.setAttribute('aria-hidden',String(!open));panel.inert=!open;syncPageLock()}
 menu?.addEventListener('click',()=>toggleMenu(menu.getAttribute('aria-expanded')!=='true'));
 $$('.topbar-mobileNavItem').forEach(a=>a.addEventListener('click',()=>toggleMenu(false)));
 document.addEventListener('pointerdown',e=>{if(menu?.getAttribute('aria-expanded')==='true'&&!shell.contains(e.target))toggleMenu(false)});
 const nav=$$('.topbar-itemLink'),indicator=$('.topbar-activeIndicator'),isHome=Boolean($('#home'));
 function setNav(hash){currentNav=hash;nav.forEach(a=>{const active=isHome&&a.hash===hash;a.classList.toggle('topbar-itemLinkActive',active);a.classList.toggle('topbar-itemLinkInactive',!active);const label=$('.topbar-itemLabel',a);label.classList.toggle('topbar-itemLabelActive',active);label.classList.toggle('topbar-itemLabelInactive',!active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});const active=nav.find(a=>isHome&&a.hash===hash);indicator?.classList.toggle('topbar-activeIndicatorVisible',Boolean(active));if(active&&indicator){indicator.style.width=active.offsetWidth+'px';indicator.style.transform=`translateX(${active.offsetLeft}px)`}$$('.topbar-mobileNavItem').forEach(a=>{const active=isHome&&a.hash===hash;a.classList.toggle('topbar-mobileNavItemActive',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}
 function updateNav(){let id=isHome?'home':'';for(const key of ['about','services','our-process','case-study','testimonials']){const el=$('#'+key);if(el&&el.getBoundingClientRect().top<innerHeight*.4)id=key}if(currentNav!==id)setNav(id?'#'+id:'');if(shell)shell.dataset.scrolled=String(scrollY>30)}
 addEventListener('scroll',()=>{if(!navFrame)navFrame=requestAnimationFrame(()=>{navFrame=0;updateNav()})},{passive:true});addEventListener('resize',()=>{if(innerWidth>=1024)toggleMenu(false);setNav(currentNav)});document.fonts.ready.then(()=>setNav(currentNav));setNav(isHome?'#home':'');
 const closeTimers=new WeakMap();let dialogOrigin;
 function closeDialog(dialog){if(!dialog?.open||dialog.hasAttribute('data-closing'))return;if(reduced.matches){dialog.close();return}dialog.setAttribute('data-closing','');closeTimers.set(dialog,setTimeout(()=>{dialog.close();dialog.removeAttribute('data-closing');closeTimers.delete(dialog)},180))}
 function openDialog(dialog){if(!dialog)return;dialogOrigin=document.activeElement;$$('dialog').forEach(d=>{clearTimeout(closeTimers.get(d));d.removeAttribute('data-closing');if(d.open)d.close()});toggleMenu(false);dialog.showModal();document.body.classList.add('dialog-open');syncPageLock()}
 $$('[data-contact]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();openDialog($('#contact-dialog'))}));
 $$('.blitz-dialog').forEach(dialog=>{$('.dialog-close',dialog)?.addEventListener('click',()=>closeDialog(dialog));dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog(dialog)});dialog.addEventListener('close',()=>{if(!$('dialog[open]'))document.body.classList.remove('dialog-open');syncPageLock();dialogOrigin?.focus({preventScroll:true})});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(dialog)}})});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){toggleMenu(false);menu?.focus({preventScroll:true})}if(e.key==='Tab'&&menu?.getAttribute('aria-expanded')==='true'){const controls=[menu,...$$('a',panel)],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 const footer=$('footer');if(footer)new IntersectionObserver(entries=>document.body.classList.toggle('footer-in-view',entries[0].isIntersecting),{threshold:.25}).observe(footer);
 document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target||a.hasAttribute('download'))return;const destination=new URL(a.href,location.href);if(destination.origin!==location.origin||destination.pathname===location.pathname||!/\.html$/.test(destination.pathname)||reduced.matches)return;e.preventDefault();toggleMenu(false);document.body.classList.add('page-leaving');setTimeout(()=>location.assign(destination.href),180)});
 addEventListener('pageshow',()=>document.body.classList.remove('page-leaving'));
 window.blitzUI={openDialog,closeDialog,toggleMenu};
})();
